{"explanation":"Fill half the square, then half of the remaining space, and keep repeating. After n pieces, the unfilled area is 1/2ⁿ, which approaches zero as n grows. Thus the infinite sum fills the whole square: 1/2 + 1/4 + 1/8 + ⋯ = 1.","manimCode":"const heading = new Text({ text: 'An infinite sum fills one square', fontSize: 30, color: WHITE });
heading.moveTo([0, 3.15, 0]);
const formula = new MathTex({ latex: '\\frac12 + \\frac14 + \\frac18 + \\cdots = 1' });
await formula.waitForRender();
formula.moveTo([0, 2.4, 0]);
scene.add(heading, formula);

const left = -3.9;
const bottom = -1.5;
const side = 3;
const maxSteps = 12;
let n = 1;
const palette = [BLUE, TEAL, GREEN, PURPLE, ORANGE];
const bounds = [{ x: left, y: bottom, w: side, h: side }];
const pieces = [];
function vertices(b) {
  return [[b.x, b.y, 0], [b.x + b.w, b.y, 0], [b.x + b.w, b.y + b.h, 0], [b.x, b.y + b.h, 0]];
}
for (let i = 0; i < maxSteps; i++) {
  const b = bounds[i];
  let pieceBounds;
  let nextBounds;
  if (i % 2 === 0) {
    pieceBounds = { x: b.x, y: b.y, w: b.w / 2, h: b.h };
    nextBounds = { x: b.x + b.w / 2, y: b.y, w: b.w / 2, h: b.h };
  } else {
    pieceBounds = { x: b.x, y: b.y, w: b.w, h: b.h / 2 };
    nextBounds = { x: b.x, y: b.y + b.h / 2, w: b.w, h: b.h / 2 };
  }
  const tile = new Polygon({ vertices: vertices(pieceBounds), color: palette[i % palette.length] });
  tile.setFill(palette[i % palette.length], 0.9);
  tile.setStrokeWidth(1);
  pieces.push(tile);
  bounds.push(nextBounds);
}
const outline = new Square({ sideLength: side, color: WHITE });
outline.moveTo([left + side / 2, 0, 0]);
outline.setFillOpacity(0);
const remainder = new Polygon({ vertices: vertices(bounds[n]), color: YELLOW });
remainder.setFill(YELLOW, 0.12);
remainder.setStrokeWidth(2);

const firstLabel = new MathTex({ latex: '\\frac12', color: WHITE });
const secondLabel = new MathTex({ latex: '\\frac14', color: WHITE });
const thirdLabel = new MathTex({ latex: '\\frac18', color: WHITE });
await Promise.all([firstLabel.waitForRender(), secondLabel.waitForRender(), thirdLabel.waitForRender()]);
firstLabel.moveTo([-3.15, 0, 0]);
secondLabel.moveTo([-1.65, -0.75, 0]);
thirdLabel.moveTo([-2.025, 0.75, 0]);
thirdLabel.scale(0.75);

const countLabel = new Text({ text: '', fontSize: 25, color: WHITE });
countLabel.moveTo([2.25, 1.25, 0]);
const filledLabel = new Text({ text: '', fontSize: 25, color: TEAL });
filledLabel.moveTo([2.25, 0.55, 0]);
const gapLabel = new Text({ text: '', fontSize: 24, color: YELLOW });
gapLabel.moveTo([2.25, -0.1, 0]);
const button = new Rectangle({ width: 2.8, height: 0.65, color: YELLOW });
button.moveTo([2.25, -1.05, 0]);
button.setFill(YELLOW, 0.15);
const buttonLabel = new Text({ text: 'Add next half', fontSize: 23, color: YELLOW });
buttonLabel.moveTo([2.25, -1.05, 0]);
const resetLabel = new Text({ text: 'Reset', fontSize: 21, color: GRAY });
resetLabel.moveTo([2.25, -1.85, 0]);
const limitNote = new Text({ text: 'The gap approaches 0; the filled area approaches 1.', fontSize: 23, color: WHITE });
limitNote.moveTo([0, -2.65, 0]);
const hint = new Text({ text: 'Click the yellow remainder or “Add next half”.', fontSize: 21, color: GRAY });
hint.moveTo([0, -3.25, 0]);

await scene.play(new Create(outline));
scene.add(...pieces, remainder, firstLabel, secondLabel, thirdLabel, countLabel, filledLabel, gapLabel, button, buttonLabel, resetLabel, limitNote, hint);
// Keep the border above the filled pieces.
scene.remove(outline);
scene.add(outline);
function update() {
  pieces.forEach((tile, i) => tile.setOpacity(i < n ? 1 : 0));
  remainder.setVertices(vertices(bounds[n]));
  firstLabel.setOpacity(n >= 1 ? 1 : 0);
  secondLabel.setOpacity(n >= 2 ? 1 : 0);
  thirdLabel.setOpacity(n >= 3 ? 1 : 0);
  countLabel.setText(n + (n === 1 ? ' piece added' : ' pieces added'));
  filledLabel.setText('Filled = ' + (1 - Math.pow(2, -n)).toFixed(6));
  gapLabel.setText(n === 0 ? 'Unfilled = 1' : 'Unfilled = 1/' + Math.pow(2, n));
  buttonLabel.setText(n === maxSteps ? 'Start again' : 'Add next half');
}
function advance() {
  n = n === maxSteps ? 0 : n + 1;
  update();
}
update();
makeClickable(remainder, scene, { onClick: advance });
makeClickable(button, scene, { onClick: advance });
makeClickable(buttonLabel, scene, { onClick: advance });
makeClickable(resetLabel, scene, { onClick: () => { n = 0; update(); } });
await scene.wait(999999);"}

